const res = $input.first().json;
const tree = res.tree || [];
const branch = $('Get Repo').first().json.default_branch;
const cfg = $('Config').first().json;
const repo = cfg.repo;
const sub = (cfg.subdir || '').replace(/\/$/, '');
const EXT = /\.(js|jsx|ts|tsx|vue|svelte|html|hbs|mjml|njk|ejs|json|svg)$/i;
const SKIP = /(^|\/)(node_modules|dist|build|\.next|coverage|__tests__|__mocks__|mocks?|fixtures|storybook|\.storybook|e2e|cypress|playwright)(\/|$)|\.(test|spec|stories)\.[jt]sx?$|\.d\.ts$|(package-lock|yarn\.lock|pnpm-lock)|(^|\/)package\.json$|(^|\/)tsconfig[^/]*$/i;
const isEn = p => /(^|\/)(en|en-US|en_US)(\.json|\/[^/]+\.json)$/.test(p);
let files = tree.filter(t => t.type === 'blob' && EXT.test(t.path) && !SKIP.test(t.path) && (t.size || 0) < 600000 && (!sub || t.path.startsWith(sub + '/')));
files = files.filter(t => !/\.json$/i.test(t.path) || isEn(t.path));
const total = files.length;
const capped = total > 1500;
files = files.slice(0, 1500);
if (!files.length) return [{ json: { skip: true, tree_truncated: !!res.truncated } }];
return files.map((f, i) => ({ json: { repo, branch, path: f.path, meta: i === 0 ? { total, capped, tree_truncated: !!res.truncated } : undefined } }));

// Read-only. Scoped to the qr-code-minimum-size page: returns only the files that reference this page and the matching English source keys, so code_scan.js can run on them locally.
const items = $input.all().map(i => i.json).filter(j => j && j.path && typeof j.content === 'string');
const NEEDLE = /qr[_-]code[_-]minimum[_-]size|qrCodeMinimumSize|QrCodeMinimumSize|minimum[_-]size/i;
const EN = /(^|\/)(en|en-US|en_US)(\.json|\/[^/]+\.json)$/;
const flat = (o, p = '', out = {}) => { if (o && typeof o === 'object' && !Array.isArray(o)) { for (const [k, v] of Object.entries(o)) { const key = p ? p + '.' + k : k; if (v && typeof v === 'object' && !Array.isArray(v) && !('one' in v || 'other' in v)) flat(v, key, out); else out[key] = v; } } return out; };
const enFiles = [], pageFiles = [], enKeysTotal = {};
for (const f of items) {
  if (EN.test(f.path)) {
    try { const all = flat(JSON.parse(f.content)); const ks = Object.keys(all); enKeysTotal[f.path] = ks.length; const hit = {}; for (const k of ks) if (NEEDLE.test(k)) hit[k] = all[k]; enFiles.push({ path: f.path, page_keys: hit }); } catch (e) { enFiles.push({ path: f.path, error: 'parse' }); }
  } else if (NEEDLE.test(f.content) || NEEDLE.test(f.path)) {
    pageFiles.push({ path: f.path, content: f.content.slice(0, 120000) });
  }
}
return [{ json: { files_scanned: items.length, en_files: enFiles, en_key_totals: enKeysTotal, page_files: pageFiles } }];

const src = $('Loop Files').itemMatching($itemIndex).json;
const c = $json.data;
if (src.skip) return { json: { skip: true } };
return { json: { repo: src.repo, path: src.path, content: typeof c === 'string' ? c : (c == null ? null : JSON.stringify(c)), dnt: $('Config').first().json.dnt } };
